function stackedBar(target,rows,kind,limit=8,workType=''){const root=$(target);root.replaceChildren();const selected=rows.slice(0,limit);const selectedIds=new Set(selected.map(r=>r.id));const other=rows.filter(r=>!selectedIds.has(r.id)).reduce((n,r)=>n+r.count,0),total=rows.reduce((n,r)=>n+r.count,0)||1;if(other)selected.push({id:'other',label:'Other',count:other,denominator:total,percentage:100*other/total});const bar=el('div',null,'stacked-track'),legend=el('div',null,'stacked-legend'),nodes=[];const highlight=index=>nodes.forEach(([segment,item],i)=>{segment.classList.toggle('dimmed',i!==index);item.classList.toggle('dimmed',i!==index)}),clear=()=>nodes.flat().forEach(node=>node.classList.remove('dimmed'));selected.forEach((r,i)=>{const colour=r.id==='other'?'#c3cbcc':`hsl(${Math.round(i*137.508)%360} 48% ${38+(i%3)*8}%)`,seg=el(r.id==='other'?'span':'button',null,'stacked-segment');seg.style.width=Math.max(0,r.percentage)+'%';seg.style.background=colour;seg.title=`${r.label}: ${number(r.count)} of ${number(r.denominator||total)} (${pct(r.percentage)})`;if(r.id!=='other')seg.addEventListener('click',()=>openWorks(kind,r.id,r.label,workType));bar.append(seg);const item=el('div',null,'legend-item'),swatch=el('i');item.tabIndex=0;swatch.style.background=colour;item.append(swatch,el('span',r.label),el('b',`${number(r.count)} / ${number(r.denominator||total)} · ${pct(r.percentage)}`));legend.append(item);nodes.push([seg,item]);for(const node of [seg,item]){node.addEventListener('mouseenter',()=>highlight(i));node.addEventListener('mouseleave',clear);node.addEventListener('focus',()=>highlight(i));node.addEventListener('blur',clear)}});root.append(bar,legend)}

function metric(label,value,note){const box=el('div',null,'metric');box.append(el('span',label,'metric-label'),el('strong',value),el('small',note));return box}
function citationMetric(label,value,note,kind){const box=el('button',null,'metric citation-metric');box.type='button';box.append(el('span',label,'metric-label'),el('strong',value),el('small',note+' · inspect works →'));box.addEventListener('click',()=>openWorks(kind,'true',label));return box}
function barScale(rows){const maximum=Math.max(0,...rows.map(row=>Number(row.percentage)||0)),ceilings=[1,2,5,10,25,50,75,100],ceiling=ceilings.find(value=>value>=maximum)||100;return{ceiling,midpoint:ceiling/2}}
function barScaleAxis(scale){const axis=el('div',null,'bar-scale'),plot=el('span',null,'bar-scale-axis');plot.append(el('span','0%'),el('span',`${number(scale.midpoint)}%`),el('span',`${number(scale.ceiling)}%`));axis.append(el('span','Share of works','bar-scale-title'),plot);return axis}
function staticBars(target,rows,limit=8){const root=$(target);root.replaceChildren();const display=rows.slice(0,limit);if(!display.length){root.append(el('p','No observations available.','muted'));return}const scale=barScale(display);root.append(barScaleAxis(scale));for(const row of display){const line=el('div',null,'bar-row'),top=el('span',null,'bar-top'),track=el('span',null,'track'),fill=el('span',null,'fill'),denominator=row.denominator==null?'':` of ${number(row.denominator)}`;top.append(el('span',row.label,'bar-label'),el('span',`${number(row.count)}${denominator} · ${pct(row.percentage)}`,'bar-value'));fill.style.width=Math.min(100,Math.max(0,100*(row.percentage||0)/scale.ceiling))+'%';track.append(fill);line.append(top,track);root.append(line)}}
