function render(){const p=portrait;venueVersion++;fundingVersion++;renderedSections=new Set();$('empty').hidden=true;$('portrait').hidden=false;$('institution-name').textContent=p.identity.display_name;$('identity-line').textContent=[p.identity.country_code,p.identity.type,p.identity.ror].filter(Boolean).join(' · ');$('period-label').textContent=p.corpus.period.from.slice(0,4)+'–'+p.corpus.period.to.slice(0,4);$('retrieval-label').textContent='Snapshot retrieved '+new Date(p.retrieved_at).toLocaleDateString('en-GB');$('verdict-line').textContent=p.coverage_assessment.line;$('briefing-copy').replaceChildren(...p.briefing.sentences.map(s=>el('p',s.text)));$('briefing-rules').textContent=p.briefing.rules;renderCoverageFlags();venueState=p.venues;$('venue-type').replaceChildren(el('option','All work types'));$('venue-type').firstChild.value='';for(const row of p.groups.types){const option=el('option',row.id==='unknown'?'Unknown / missing':row.label);option.value=row.id;$('venue-type').append(option)}if(p.groups.types.some(r=>r.id==='article'))$('venue-type').value='article';$('affiliation-detail').hidden=false;$('affiliation-expand').textContent='Hide affiliation evidence ↑';setupTabs();renderCoverage();renderDiagnostics();renderOutput();renderSubjectsTypes();renderCitations();renderVenues();renderCollaboration();renderFunding();for(const [id] of reportSections)renderedSections.add(id);renderedSections.delete('researchers');renderedSections.delete('affiliations');showSummary()}
function renderCoverageFlags(){const labels={primary_subject:'Field classified',doi:'DOI present',abstract:'Abstract present',primary_source:'Main source recorded'},explanations={primary_subject:'Missing classification limits subject comparisons.',doi:'Missing DOIs limit matching and deduplication.',abstract:'Missing abstracts limit text and semantic analysis.',primary_source:'Missing main sources limit source and publisher analysis.'},links={primary_subject:['See Field breakdown →','field-details'],doi:['See DOI breakdown →','doi-details'],abstract:['See Abstract breakdown →','abstract-details'],primary_source:['See source breakdown →','source-details']};$('quality-strip').replaceChildren(...portrait.coverage_assessment.metrics.map(m=>{const card=el('article',null,'coverage-flag'),drill=el('button',links[m.key][0],'text-button coverage-drill');drill.type='button';drill.addEventListener('click',()=>openCoverageDetail(links[m.key][1]));card.append(el('b',labels[m.key]),el('span',pct(m.percentage)),el('p',explanations[m.key]),drill);return card}))}
