function renderOutput(){const rows=portrait.groups.annual;lineChart('annual-chart',rows);renderMixTrend('type-trend',portrait.work_type_trend,(portrait.groups.types||[]).filter(r=>r.id!=='unknown').slice(0,6),'type','Other types');renderMixTrend('field-trend',portrait.field_trend,(portrait.groups.subjects||[]).slice(0,6),'subject','Other / unclassified');$('annual-note').textContent=rows.some(r=>!r.complete_year)?'The final year is incomplete, so do not read it as a drop in output.':'The chart starts at zero and covers complete calendar years only. Select Browse works to see the underlying records.';renderedSections.add('output')}
function renderMixTrend(target,trend,ids,kind,otherLabel,interactive=true){
  const root=$(target);root.replaceChildren();if(!trend?.length){root.append(el('p','No yearly composition data are available.','muted'));return}
  const colours=Object.fromEntries(ids.map((r,i)=>[r.id,palette[i]])),shownIds=ids.map(r=>r.id),plot=el('div',null,'type-plot'),readout=el('div','Hover over a segment or legend item for its count and share.','mix-readout'),legend=el('div',null,'type-legend');
  const highlight=id=>{for(const seg of plot.querySelectorAll('.type-segment')){seg.classList.toggle('active',seg.dataset.category===id);seg.classList.toggle('dimmed',seg.dataset.category!==id)}for(const item of legend.querySelectorAll('button')){item.classList.toggle('active',item.dataset.category===id);item.classList.toggle('dimmed',item.dataset.category!==id)}};
  const clear=()=>root.querySelectorAll('.active,.dimmed').forEach(node=>node.classList.remove('active','dimmed'));
  const bindHighlight=(node,id,message)=>{node.addEventListener('mouseenter',()=>{highlight(id);if(message)readout.textContent=message});node.addEventListener('mouseleave',()=>{clear();readout.textContent='Hover over a segment or legend item for its count and share.'});node.addEventListener('focus',()=>{highlight(id);if(message)readout.textContent=message});node.addEventListener('blur',()=>{clear();readout.textContent='Hover over a segment or legend item for its count and share.'})};
  for(const year of trend){const col=el('div',null,'type-year'),stack=el('div',null,'type-stack');if(!year.total){stack.classList.add('empty-year');stack.title=`${year.year}: no linked works`;col.append(stack,el('span',year.year));plot.append(col);continue}const visible=year.rows.filter(r=>colours[r.id]).sort((a,b)=>(b.percentage||0)-(a.percentage||0)),visibleShare=visible.reduce((n,r)=>n+(r.percentage||0),0),other=Math.max(0,100-visibleShare);for(const row of visible){const seg=el('button',null,'type-segment');seg.type='button';seg.dataset.category=row.id;seg.style.height=Math.max(1,row.percentage||0)+'%';seg.style.background=colours[row.id];const message=`${year.year} · ${row.label}: ${number(row.count)} works (${pct(row.percentage)})`;seg.setAttribute('aria-label',message);bindHighlight(seg,row.id,message);if(interactive)seg.addEventListener('click',()=>openWorks(kind,row.id,row.label,'',year.year));stack.append(seg)}if(other>.05){const gap=el('button',null,'type-segment other');gap.type='button';gap.dataset.category='other';gap.style.height=other+'%';const message=`${year.year} · ${otherLabel}: ${pct(other)}`;gap.setAttribute('aria-label',message);bindHighlight(gap,'other',message);if(interactive)gap.addEventListener('click',()=>openOtherBreakdown(kind,year.year,shownIds,otherLabel));stack.append(gap)}col.append(stack,el('span',year.year));plot.append(col)}
  for(const row of [...ids,{id:'other',label:otherLabel}]){const item=el('button');item.type='button';item.dataset.category=row.id;const swatch=el('i');if(row.id==='other')swatch.className='other';else swatch.style.background=colours[row.id];item.append(swatch,document.createTextNode(row.label));bindHighlight(item,row.id);legend.append(item)}
  root.append(plot,readout,legend)
}
async function openOtherBreakdown(kind,year,selectedIds,label){const version=++worksVersion,p=portrait;worksState=null;$('works-title').textContent=`${label} · ${year}`;$('works-meta').textContent='Loading the categories combined into the grey remainder…';$('works-footnote').textContent='Counts use the same whole-work yearly population as the chart.';$('works-list').replaceChildren();$('page-label').textContent='';$('previous').disabled=true;$('next').disabled=true;$('works-dialog').showModal();try{const params=new URLSearchParams({institution:p.identity.id,start:p.corpus.period.from.slice(0,4),end:p.corpus.period.to.slice(0,4),year,kind}),data=await api('/api/composition?'+params);if(version!==worksVersion)return;const visible=new Set(selectedIds),rows=data.rows.filter(r=>!visible.has(r.id));$('works-meta').textContent='Categories combined into the grey remainder. Select one to browse its works for this year.';for(const row of rows){const b=el('button',null,'candidate');b.append(el('strong',row.label),el('span',`${number(row.count)} works · ${pct(row.percentage)} · browse →`));b.addEventListener('click',()=>openWorks(kind,row.id,row.label,'',year));$('works-list').append(b)}if(!rows.length)$('works-list').append(el('p','No additional named categories are available.','muted'));$('page-label').textContent=`${rows.length} component categories`}catch(e){if(version===worksVersion)$('works-meta').textContent=e.message}}
function setupTabs(){const nav=$('explore-tabs');nav.replaceChildren();for(const [id,label] of reportSections){const b=el('button',label);b.dataset.section=id;b.addEventListener('click',()=>selectSection(id));nav.append(b)}}
function prepareLayout(){
  const p=portrait,output=sectionNodes.output,gaps=sectionNodes['metadata-patterns'],coverage=$('coverage');
  document.querySelector('.portrait-heading .step').textContent='OpenAlex coverage report';
  $('identity-line').textContent=[p.identity.country_code,p.identity.type,p.identity.ror].filter(Boolean).join(', ');
  let intro=$('overview-intro');
  if(!intro){intro=el('div',null,'overview-intro');output.prepend(intro)}
  const total=p.population.eligible_works;
  const headline=el('div',null,'headline-strip'),headlineText=el('div',null,'headline-copy');
  headlineText.append(el('p',`OpenAlex records ${number(total)} works for ${p.identity.display_name} in this period.`));
  const scope=el('div',null,'headline-coverage-scope'),scopeLabel=el('span','Show evidence for'),scopeButtons=el('div',null,'segmented'),stats=el('div',null,'headline-smart-view'),boundary=el('p',null,'headline-boundary'),coverageFor=type=>{if(!type)return {subject:p.coverage.primary_subject,abstract:p.coverage.abstract};const total=(p.groups.types||[]).find(row=>row.id===type)?.count||0,missing=(p.diagnostics?.unclassified_subject?.by_work_type||[]).find(row=>row.id===type)?.count||0,abstract=(p.diagnostics?.abstracts?.by_work_type||[]).find(row=>row.id===type)||{count:0,denominator:total,percentage:total?0:null};return {subject:{count:Math.max(0,total-missing),denominator:total,percentage:total?100*(total-missing)/total:null},abstract}},signalFor=(key,type)=>{const signal=p.evidence_signals?.[key];return type?(signal?.by_work_type||[]).find(row=>row.id===type):signal?.overall},renderHeadlineCoverage=type=>{const values=coverageFor(type),stat=(metric,label,detail)=>{const item=el('div',null,'headline-stat'),known=metric&&metric.denominator>0;item.append(el('span',label),el('strong',known?pct(metric.percentage):'Not collected'),el('small',known?`${number(metric.count)} of ${number(metric.denominator)} works`:'Rebuild this saved report to add this signal'),el('small',detail,'headline-stat-detail'));return item},analysis=el('section',null,'headline-smart-group'),funding=el('section',null,'headline-smart-group funding-teaser'),analysisStats=el('div',null,'headline-stats');analysis.append(el('h4','Inputs available for analysis'));analysisStats.append(stat(values.subject,'Subject classification','Primary Topic → Subfield → Field → Domain'),stat(values.abstract,'Abstract recorded','Text and semantic analysis'),stat(signalFor('references',type),'References linked','Outgoing references matched to OpenAlex Works'));analysis.append(analysisStats);funding.append(el('h4','Funding evidence'),stat(signalFor('funder',type),'Works with a matched funder','A Work-level metadata link—not recipient evidence'));const exploreFunding=el('button','Explore the funding evidence →','headline-explore');exploreFunding.type='button';exploreFunding.addEventListener('click',()=>selectSection('funding'));funding.append(exploreFunding);stats.replaceChildren(analysis,funding);for(const button of scopeButtons.children)button.setAttribute('aria-pressed',String(button.dataset.type===type));const label=type==='article'?'articles':type==='preprint'?'preprints':'Works';boundary.textContent=`These are recorded evidence rates among ${label} already in this OpenAlex snapshot—not completeness or quality scores. Missing ${label} require comparison with an independent source.`};
  for(const [type,label] of [['','All works'],['article','Articles'],['preprint','Preprints']]){const button=el('button',label);button.type='button';button.dataset.type=type;button.addEventListener('click',()=>renderHeadlineCoverage(type));scopeButtons.append(button)}scope.append(scopeLabel,scopeButtons);headline.append(headlineText,scope,stats,boundary);renderHeadlineCoverage('');
  const read=el('p',null,'how-to-read');
  read.append(document.createTextNode('How to read this: first check whether the output trend and subject mix look plausible. Then use '));
  const gapLink=el('button','Coverage gaps','inline-link');gapLink.addEventListener('click',()=>selectSection('metadata-patterns'));
  read.append(gapLink,document.createTextNode(' to inspect missing records and see which analyses the data can support.'));
  intro.replaceChildren(headline,read);
  const actions=$('coverage-actions'),method=coverage.querySelector('.method-compact');
  let toolbar=$('report-toolbar');
  if(!toolbar){toolbar=el('div',null,'report-toolbar');toolbar.id='report-toolbar';const exportControls=document.querySelector('.export-controls'),scope=document.querySelector('.inline-definitions');exportControls.querySelector('label').textContent='Export';toolbar.append(scope,exportControls);$('explore-view').insertBefore(toolbar,$('explore-tabs'))}
  $('scope-copy').textContent=`This report is a snapshot of OpenAlex data about ${p.identity.display_name}${p.identity.ror?' using ROR '+p.identity.ror.replace('https://ror.org/',''):''}. It aggregates Works linked to this organisation. Coverage gaps show missing metadata, which can reflect publisher deposits, restricted availability, or incomplete indexing. Affiliations shows the raw wording OpenAlex used to identify the organisation, including its core name and sub-affiliations such as departments and laboratories. Subject percentages use only Works with a primary Topic; each Topic belongs to a Subfield, Field and Domain.`;
  let actionWrap=$('gap-actions');
  if(!actionWrap){actionWrap=el('section',null,'gap-actions');actionWrap.append(el('h4','Records to inspect'),el('p','Counts are from the saved snapshot; opening a list performs a clearly labelled live lookup.','muted'),actions);gaps.insertBefore(actionWrap,gaps.querySelector('.insight-grid'))}
  if(method&&!gaps.contains(method))gaps.append(method);
  const fundingColumns=$('funding').querySelectorAll('.two-column>div');
  for(const badge of $('funding').querySelectorAll('.data-origin'))badge.remove();
  coverage.hidden=true;
  for(const card of document.querySelectorAll('.status-chip'))card.hidden=true
}
function showSummary(){prepareLayout();$('summary-view').hidden=true;$('explore-view').hidden=false;selectSection(activeSection)}
function showExplore(){$('summary-view').hidden=true;$('explore-view').hidden=false;selectSection(activeSection)}
function selectSection(id){activeSection=id;const node=sectionNodes[id];$('explore-panel').replaceChildren(node);for(const b of $('explore-tabs').children)b.setAttribute('aria-pressed',String(b.dataset.section===id));if(renderedSections.has(id))return;if(id==='subjects-types')renderSubjects();if(id==='outputs-access')renderOutputsAccess();if(id==='citations')renderCitations();if(id==='researchers')renderResearchers();if(id==='funding')renderFunding();if(id==='metadata-patterns')renderDiagnostics();if(id==='collaboration')renderCollaboration();if(id==='venues'){if($('venue-type').value!==(venueState.work_type||''))$('venue-type').dispatchEvent(new Event('change'));else renderVenues();}if(id==='affiliations')renderAffiliations();renderedSections.add(id)}
function renderCoverage(){const p=portrait;$('coverage-grid').replaceChildren();for(const [key,label] of [['primary_subject','Primary Field'],['doi','DOI present'],['abstract','Abstract present'],['primary_source','Primary source']]){const m=p.coverage[key],box=el('div',null,'coverage-item');box.append(el('span',label),el('strong',pct(m.percentage)),el('small',`${number(m.count)} of ${number(m.denominator)} snapshot works`));$('coverage-grid').append(box)}const actions=[['subject','unknown','Missing Field',p.population.unclassified_works,'Review before subject analysis'],['doi','false','Missing DOI',p.population.eligible_works-p.coverage.doi.count,'Check matching and deduplication'],['abstract','false','Missing abstract',p.population.eligible_works-p.coverage.abstract.count,'Audit text-analysis bias'],['source','unknown','Missing primary source',p.population.eligible_works-p.coverage.primary_source.count,'Review venue analysis']];$('coverage-actions').replaceChildren(...actions.map(([kind,value,label,count,note])=>{const b=el('button',null,'action-card');b.append(el('span',label),el('strong',number(count)),el('small',note+' · inspect live records →'));b.addEventListener('click',()=>openWorks(kind,value,label));return b}));$('warnings').replaceChildren(...p.warnings.map(w=>el('li',w)));$('warnings').append(el('li',`${number(p.retracted_works.count)} works are flagged as retracted and retained in this report.`));const estimate=p.full_download_estimate;$('download-note').textContent=`A complete, frozen record download is a separate CLI action: estimated ${number(estimate.estimated_calls)} API calls and approximately $${estimate.estimated_api_cost_usd.toFixed(4)} at rates dated ${estimate.rate_card.as_of}. This saved report contains aggregates, not every record.`;$('source-links').replaceChildren(link('Inspect institution on OpenAlex',p.identity.id))}
const renderCoverageBase=renderCoverage;
renderCoverage=function(){renderCoverageBase();const p=portrait,estimate=p.full_download_estimate,warnings=$('warnings');if(warnings.lastChild)warnings.lastChild.textContent=`This report keeps ${number(p.retracted_works.count)} works that OpenAlex flags as retracted, so retraction status does not change the headline counts.`;$('download-note').textContent=`This saved report holds aggregate counts rather than every individual record. A complete record download is a separate CLI action: about ${number(estimate.estimated_calls)} API calls and approximately $${estimate.estimated_api_cost_usd.toFixed(4)}, using rates dated ${estimate.rate_card.as_of}.`};
function renderSubjects(){const p=portrait;$('subject-note').textContent=`Percentages are based on ${number(p.population.classified_works)} classified works. Another ${number(p.population.unclassified_works)} works (${pct(100*p.population.unclassified_works/p.population.eligible_works)}) have no Field assigned and are excluded from these shares.`;stackedBar('subject-chart',p.groups.subjects,'subject',26);staticBars('subfield-chart',p.groups.subfields||[],12);staticBars('topic-chart',p.groups.topics||[],12);$('sdg-summary').textContent='OpenAlex predicts SDG relevance from titles and abstracts and keeps tags scoring above 0.4. Select a goal to inspect the tagged works.';const sdg=p.groups.sdg_summary||{},tagged=sdg.tagged_works||{};$('sdg-stats').replaceChildren(metric('Works with at least one predicted goal',pct(tagged.percentage),`${number(tagged.count||0)} of ${number(tagged.denominator||p.population.eligible_works)} works`),metric('Average tags per tagged work',sdg.average_tags_per_tagged_work==null?'Unknown':sdg.average_tags_per_tagged_work.toFixed(1),`${number(sdg.tag_assignments||0)} tag assignments`));bars('sdg-chart',p.groups.sdgs||[],'sdg',17);const rows=(p.groups.domains||[]).filter(r=>r.id!=='unknown'),root=$('domain-chart'),bar=el('div',null,'domain-stack'),legend=el('div',null,'domain-legend');root.replaceChildren();for(const [i,row] of rows.entries()){const segment=el('span',null,'domain-segment');segment.style.width=row.percentage+'%';segment.style.background=palette[i%palette.length];segment.title=`${row.label}: ${pct(row.percentage)}`;bar.append(segment);const item=el('article'),swatch=el('i'),fields=p.groups.domain_fields?.[row.id]?.fields||[];swatch.style.background=palette[i%palette.length];item.append(swatch,el('strong',`${row.label} · ${pct(row.percentage)}`),el('small',fields.slice(0,3).map(f=>`${f.label} ${pct(f.percentage)}`).join(' · ')));legend.append(item)}root.append(bar,legend)}
function renderOutputsAccess(){const p=portrait;renderMixTrend('type-chart',p.work_type_trend,(p.groups.types||[]).filter(r=>r.id!=='unknown').slice(0,6),'type','Other types');const patent=p.groups.types.find(r=>r.id==='patent');$('patent-note').textContent=patent?`OpenAlex has ${number(patent.count)} patent records (${pct(patent.percentage)}) linked to this institution. Compare this database view with patent-office or institutional records before using it as a total.`:'No patent records are linked to this institution in the saved OpenAlex snapshot. Check patent-office or institutional records if patents are in scope.';const oa=p.open_access||{statuses:[],trend:[],definition:''},known=oa.statuses.filter(r=>r.id!=='unknown').reduce((n,r)=>n+r.count,0);$('oa-summary').textContent=`${oa.definition} A status is recorded for ${number(known)} of ${number(p.population.eligible_works)} works in this saved snapshot.`;renderMixTrend('oa-trend',oa.trend,(oa.statuses||[]).filter(r=>r.id!=='unknown'),'oa','Status not recorded')}
function renderCitations(){const c=portrait.citations||{},summary=$('citation-summary');summary.replaceChildren(metric('Cited at least once',pct(c.cited?.percentage),`${number(c.cited?.count||0)} of ${number(c.cited?.denominator||0)} works`),metric('Top 10% flag',number(c.top_10_percent?.count||0),`${pct(c.top_10_percent?.percentage)} of snapshot works`),metric('Top 1% flag',number(c.top_1_percent?.count||0),`${pct(c.top_1_percent?.percentage)} of snapshot works`));staticBars('citation-trend',(c.by_publication_year||[]).map(row=>({id:row.year,label:row.year,count:row.cited.count,denominator:row.total,percentage:row.cited.percentage})),50);$('citation-note').textContent=c.note||''}
function renderSubjectsTypes(){renderSubjects();renderOutputsAccess();renderedSections.add('subjects-types');renderedSections.add('outputs-access')}
async function renderFunding(){const f=portrait.funding,p=portrait,version=++fundingVersion,signals=p.evidence_signals;if(!f){$('funding-summary').textContent='Funding data was not collected for this saved snapshot.';return}const evidence=$('funding-evidence-ladder'),evidenceMetric=(label,row,detail)=>metric(label,pct(row?.percentage),`${number(row?.count||0)} of ${number(row?.denominator||0)} Works · ${detail}`);evidence.replaceChildren(evidenceMetric('Work has matched funder',signals?.funder?.overall,'Work metadata'),evidenceMetric('Work linked to Award record',signals?.award?.overall,'not recipient evidence'),evidenceMetric('Grant number recorded on Work',signals?.grant_number?.overall,'funder Award ID'));$('funding-summary').textContent=`A matched funder appears on ${number(f.coverage.count)} Works (${pct(f.coverage.percentage)}). This is Work-level metadata, not evidence that ${p.identity.display_name} received those grants.`;staticBars('funding-chart',f.top_funders,5);$('award-summary').textContent='Loading Awards that explicitly name this institution…';$('award-chart').replaceChildren();try{const params=new URLSearchParams({institution:p.identity.id,start:p.corpus.period.from.slice(0,4),end:p.corpus.period.to.slice(0,4)}),a=await api('/api/funding-details?'+params);if(version!==fundingVersion||portrait!==p)return;$('award-summary').textContent=`${number(a.institution_awards_count)} Award records explicitly name ${p.identity.display_name} as a recipient. This is a different population from the Work-level figures above. ${a.note}`;const root=$('award-chart');for(const row of a.top_awards){const card=el('article',null,'award-card');card.append(link(row.label,row.id),el('strong',`${number(row.count)} linked works`));const money=row.amount&&row.currency?`${number(row.amount)} ${row.currency}`:null,years=[row.start_year,row.end_year].filter(Boolean).join('–'),primary=[row.funder,row.funder_award_id&&'Grant '+row.funder_award_id,years,money].filter(Boolean),secondary=[row.lead_investigator&&'Lead investigator from Award record: '+row.lead_investigator,row.has_description?'Project description available':null,row.provenance&&'Award record source: '+row.provenance].filter(Boolean);if(primary.length)card.append(el('p',primary.join(' · '),'award-facts-primary'));if(secondary.length)card.append(el('p',secondary.join(' · '),'small muted award-facts-secondary'));root.append(card)}if(!a.top_awards.length)root.append(el('p','OpenAlex has no Awards that explicitly name this institution as a recipient.','muted'))}catch(e){if(version===fundingVersion)$('award-summary').textContent='Recipient-named Award records could not be loaded. Work-level funding evidence above is still available.'}}
function renderDiagnostics(){const d=portrait.diagnostics,abstracts=d.abstracts.by_year,missing=d.unclassified_subject.by_year,sources=d.primary_source.by_year,first=a=>a[0],last=a=>a.at(-1),byId=(rows,id)=>rows.find(r=>r.id===id),lowest=d.abstracts.lowest_coverage_fields.slice(0,2),article=byId(d.abstracts.by_work_type,'article'),preprint=byId(d.abstracts.by_work_type,'preprint'),doiArticle=byId(d.doi.by_work_type,'article'),doiPreprint=byId(d.doi.by_work_type,'preprint');sparkline('abstract-spark',abstracts);$('abstract-change').textContent=`${pct(first(abstracts).percentage)} → ${pct(last(abstracts).percentage)}`;$('abstract-badge').textContent=last(abstracts).percentage>first(abstracts).percentage?'Improving':'Check trend';$('abstract-badge').className='status-chip '+(last(abstracts).percentage>first(abstracts).percentage?'green':'orange');$('abstract-so-what').textContent=`Coverage is improving, but ${article?pct(article.percentage)+' of articles':''}${preprint?' and '+pct(preprint.percentage)+' of preprints':''} have abstracts. ${lowest.length?'It is lowest in '+lowest.map(r=>`${r.label} (${pct(r.percentage)})`).join(' and ')+'. ':''}OpenAlex says availability and publisher restrictions are known general causes, but it does not give a reason for each missing abstract. Abstract-dependent analysis will be least representative in the groups shown here.`;sparkline('field-spark',missing,'percentage','#c27a16');$('field-change').textContent=`${pct(first(missing).percentage)} → ${pct(last(missing).percentage)}`;$('field-badge').textContent=last(missing).percentage>Math.max(...missing.slice(0,-1).map(r=>r.percentage))*1.5?'Check '+last(missing).label:'Stable';$('field-badge').className='status-chip '+($('field-badge').textContent.startsWith('Check')?'amber':'green');$('field-so-what').textContent=`The missing-Field rate is ${pct(last(missing).percentage)} in ${last(missing).label}. Verify the newest year against a later snapshot or institutional records before relying on its subject breakdown.`;$('doi-so-what').textContent=`DOIs cover ${doiArticle?pct(doiArticle.percentage)+' of articles':''}${doiPreprint?' and '+pct(doiPreprint.percentage)+' of preprints':''}. A missing DOI does not invalidate a work. It weakens DOI-based matching, and may be expected for formats such as books and reports; use the breakdown below before judging the gap.`;sparkline('source-spark',sources,'percentage','#4d78bb');$('source-change').textContent=`${pct(first(sources).percentage)} → ${pct(last(sources).percentage)}`;$('source-badge').textContent=last(sources).percentage<first(sources).percentage?'Declining':'Stable';$('source-badge').className='status-chip '+(last(sources).percentage<first(sources).percentage?'amber':'green');const lowSource=d.primary_source.by_work_type[0];$('source-so-what').textContent=`Primary-source coverage has moved from ${pct(first(sources).percentage)} to ${pct(last(sources).percentage)}. ${lowSource?`${lowSource.label} has the lowest work-type coverage (${pct(lowSource.percentage)}).`:''} Source-based analysis should account for these unmatched records.`;staticBars('abstract-types',d.abstracts.by_work_type,10);staticBars('abstract-fields',d.abstracts.lowest_coverage_fields,5);staticBars('abstract-sources',d.abstracts.lowest_coverage_sources,5);staticBars('doi-types',d.doi.by_work_type,10);staticBars('field-gap-types',d.unclassified_subject.by_work_type,5);staticBars('field-gap-sources',d.unclassified_subject.by_primary_source,5);staticBars('source-types',d.primary_source.by_work_type,10);$('diagnostic-note').textContent='These patterns locate missing metadata. Whether the level is normal should be judged against a comparable institution or field; that benchmark is a later addition.'}
const renderDiagnosticsBase=renderDiagnostics;
renderDiagnostics=function(){renderDiagnosticsBase();const d=portrait.diagnostics,abstracts=d.abstracts.by_year,sources=d.primary_source.by_year,byId=(rows,id)=>rows.find(r=>r.id===id),article=byId(d.abstracts.by_work_type,'article'),preprint=byId(d.abstracts.by_work_type,'preprint'),doiArticle=byId(d.doi.by_work_type,'article'),doiPreprint=byId(d.doi.by_work_type,'preprint'),lowest=d.abstracts.lowest_coverage_fields.slice(0,2),first=a=>a[0],last=a=>a.at(-1),lowSource=d.primary_source.by_work_type[0];$('abstract-so-what').textContent=`${article?pct(article.percentage)+' of articles':''}${preprint?' and '+pct(preprint.percentage)+' of preprints':''} have abstracts. ${lowest.length?'Coverage is lowest in '+lowest.map(r=>`${r.label} (${pct(r.percentage)})`).join(' and ')+'. ':''}OpenAlex cites availability and publisher restrictions as general causes but does not record a reason for each missing abstract. Analysis based on abstract text will under-represent these groups most.`;$('doi-so-what').textContent=`DOIs cover ${doiArticle?pct(doiArticle.percentage)+' of articles':''}${doiPreprint?' and '+pct(doiPreprint.percentage)+' of preprints':''}. A missing DOI does not make a record wrong, but it weakens DOI-based matching and is common for formats such as books and reports. Check the breakdown below before treating the overall rate as a gap.`;$('source-so-what').textContent=`Primary-source coverage moved from ${pct(first(sources).percentage)} to ${pct(last(sources).percentage)}. ${lowSource?`${lowSource.label.charAt(0).toUpperCase()+lowSource.label.slice(1)} records have the lowest work-type coverage, at ${pct(lowSource.percentage)}. `:''}Analysis grouped by source will undercount records without a source link.`;$('diagnostic-note').textContent='These patterns show where metadata is missing. OpenAlex does not publish comparable rates for peer institutions, so treat this as the institution’s own trend rather than a benchmark.'};
function renderCollaboration(){const countries=collaboration==='countries',home=portrait.identity.country_code,homeName=home==='GB'?'UK':home;$('institution-tab').setAttribute('aria-pressed',String(!countries));$('country-tab').setAttribute('aria-pressed',String(countries));let rows=portrait.groups.institutions,kind='institution';$('home-country-stat').replaceChildren();if(countries){kind='country';const normalised=portrait.groups.countries.map(r=>({...r,id:r.id==='unknown'?'unknown':r.id.rsplit?r.id.rsplit('/',1).at(-1):r.id.split('/').at(-1)})),homeRow=normalised.find(r=>r.id===home),other=normalised.filter(r=>r.id!==home&&r.id!=='unknown'),bounded=portrait.groups.countries.length>=100;$('collaboration-headline').textContent=`Output is co-authored with institutions in ${bounded?'at least ':''}${other.length} other countries represented in this ranking.`;if(homeRow)$('home-country-stat').append(metric(`Recorded with ${homeName} institutions`,pct(homeRow.percentage),'Expected for a home-country institution; shown separately from the ranking.'));rows=other}else{const headlineRows=rows.slice(0,10),domestic=headlineRows.filter(r=>r.country_code===home).length;$('collaboration-headline').textContent=`${domestic} of the top ${headlineRows.length} collaborators are ${homeName}-based.`}$('collaboration-note').textContent='Counts overlap because one work can contain several institutions or countries. Bar lengths share one scale. Select a row to inspect the shared works.';const displayRows=rows.slice(0,10),max=Math.max(1,...displayRows.map(r=>r.count)),colourByCountry=new Map(),colours=['#34526b','#bd623f','#4f8064','#765e9e','#a27b35','#777f88'],root=$('collaboration-chart'),legend=el('div',null,'collaboration-legend');root.replaceChildren();for(const row of displayRows){const country=kind==='institution'?(row.country_code||'Unknown'):row.id;if(!colourByCountry.has(country))colourByCountry.set(country,colours[colourByCountry.size%colours.length]);const button=el('button',null,'collaboration-bar-row'),head=el('span',null,'collaboration-bar-head'),track=el('span',null,'collaboration-bar-track'),fill=el('i');head.append(el('span',row.label),el('b',`${number(row.count)} · ${pct(row.percentage)}`));fill.style.width=100*row.count/max+'%';fill.style.background=colourByCountry.get(country);track.append(fill);button.append(head,track);button.addEventListener('click',()=>openWorks(kind,row.id,row.label));root.append(button)}for(const [country,colour] of colourByCountry){const item=el('span'),swatch=el('i');swatch.style.background=colour;item.append(swatch,document.createTextNode(country));legend.append(item)}root.append(legend)}
$('institution-tab').addEventListener('click',()=>{collaboration='institutions';renderCollaboration()});$('country-tab').addEventListener('click',()=>{collaboration='countries';renderCollaboration()});$('all-publications').addEventListener('click',()=>openWorks('','','All publications'));
$('explore-report').addEventListener('click',showExplore);$('back-summary').addEventListener('click',showSummary);$('affiliation-expand').addEventListener('click',()=>{const detail=$('affiliation-detail');detail.hidden=!detail.hidden;$('affiliation-expand').textContent=detail.hidden?'Inspect affiliation evidence →':'Hide affiliation evidence ↑'});
async function openWorks(kind,value,label,workType='',year=''){$('dialog-data-state').textContent='LIVE LOOKUP';$('works-footnote').textContent=portrait.report_type==='researcher'?'Fetched now for this OpenAlex Author profile. These results may not match the saved snapshot because OpenAlex updates continuously.':'Fetched now using the saved institution and period filters. These results may not match the saved snapshot because OpenAlex updates continuously.';worksState={kind,value,label,page:1,workType,year};$('works-dialog').showModal();loadWorks()}
function renderWorkRecord(row){const item=el('article',null,'work');item.append(link(row.display_name||'Untitled work',row.id));const source=row.primary_location?.source?.display_name||'Source unknown';item.append(el('p',`${row.publication_year??'Year unknown'} · ${row.type??'Type unknown'} · ${source}`));if(row.doi)item.append(link('DOI ↗',row.doi));return item}
async function loadWorks(){const version=++worksVersion,w=worksState,p=portrait,researcher=p.report_type==='researcher',from=w.year||(researcher?'0':p.corpus.period.from.slice(0,4)),to=w.year||(researcher?'0':p.corpus.period.to.slice(0,4));visibleRecords=[];$('export-records').hidden=true;$('works-title').textContent=w.label+(w.year?' · '+w.year:'');$('works-meta').textContent='Loading matching publications…';$('works-list').replaceChildren();$('previous').disabled=true;$('next').disabled=true;$('page-label').textContent='';try{const params=new URLSearchParams({institution:p.identity.id,start:from,end:to,kind:w.kind,value:w.value,page:String(w.page),work_type:w.workType||''});const data=await api('/api/publications?'+params);if(version!==worksVersion)return;visibleRecords=data.results;$('export-records').hidden=!visibleRecords.length;const period=researcher&&!w.year?'all years':from+(from===to?'':'–'+to);$('works-meta').textContent=`${number(data.count)} matching works · ${period}${w.workType?' · '+w.workType:''} · Newest first`;$('page-label').textContent=`Page ${data.page} of ${number(Math.max(1,Math.ceil(data.count/20)))}`;for(const row of data.results)$('works-list').append(renderWorkRecord(row));if(!data.results.length)$('works-list').append(el('p','No publications match this selection. The index may have changed.'));$('previous').disabled=data.page<=1;$('next').disabled=data.page*20>=data.count||data.page>=500}catch(e){if(version===worksVersion)$('works-meta').textContent=e.message}}
$('previous').addEventListener('click',()=>{worksState.page--;loadWorks()});$('next').addEventListener('click',()=>{worksState.page++;loadWorks()});$('close-dialog').addEventListener('click',()=>{$('works-dialog').close();worksVersion++});$('works-dialog').addEventListener('close',()=>{worksVersion++});
$('export-records').addEventListener('click',()=>{if(!visibleRecords.length)return;const quote=v=>'"'+String(v??'').replaceAll('"','""')+'"',rows=[['OpenAlex ID','Title','DOI','Publication year','Type','Primary source'],...visibleRecords.map(r=>[r.id,r.display_name,r.doi,r.publication_year,r.type,r.primary_location?.source?.display_name])],blob=new Blob(['\ufeff'+rows.map(row=>row.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='pharos-visible-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});
$('export').addEventListener('click',async()=>{const button=$('export');button.disabled=true;const format=$('export-format').value;$('export-status').textContent='Preparing '+format.toUpperCase()+'…';try{const response=await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job:exportJob,format,venue_id:venueState?.view_id||null})});if(!response.ok){const data=await response.json();throw new Error(data.error||'Export failed.')}const blob=await response.blob(),url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='pharos-coverage.'+format;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('export-status').textContent='Download ready.'}catch(e){$('export-status').textContent=e.message}finally{button.disabled=false}});

async function refreshSaved(){try{const config=await api('/api/config'),labels={institution:'Organisation',author:'Researcher',funder:'Funder',source:'Journal / source',publisher:'Publisher'};$('start').max=config.current_year;$('end').max=config.current_year;$('end').value=Math.min(Number($('end').value)||config.current_year-1,config.current_year-1);$('saved-list').replaceChildren();for(const saved of config.saved.slice(0,20)){const period=saved.kind==='author'?'Complete career':saved.start?`${saved.start}–${saved.end}`:'Legacy all-years snapshot',b=el('button',saved.name);b.append(el('span',`${labels[saved.kind]||'Report'} · ${period} · ${number(saved.count)} works`));b.addEventListener('click',()=>{const radio=document.querySelector(`input[name="entity-kind"][value="${saved.kind}"]`);if(radio){radio.checked=true;radio.dispatchEvent(new Event('change'))}choose({id:saved.institution,display_name:saved.name});if(saved.start){$('start').value=saved.start;$('end').value=saved.end}updatePeriodControls();build(saved.institution,saved.kind==='author'?0:(saved.start||2012),saved.kind==='author'?0:(saved.end||config.current_year-1),saved.kind)});$('saved-list').append(b)}if(!config.saved.length)$('saved-list').append(el('p','Every coverage report you build will appear here.','small muted'));return config}catch(e){notice(e.message,true)}}
refreshSaved();
