const workTypeDefinitions={article:'Research article in a journal or similar source.',preprint:'Manuscript shared before or alongside formal publication.',review:'Synthesis of existing research.',dataset:'Structured research data published as an output.',book:'Complete scholarly book or monograph.','book-chapter':'Chapter published within a book.','conference-paper':'Full paper associated with a conference.','conference-abstract':'Short conference abstract rather than a full paper.',report:'Research or technical report.',editorial:'Editorial or opinion-led publication.',letter:'Letter or correspondence item.',patent:'Patent record linked by OpenAlex.',dissertation:'Thesis or dissertation.',standard:'Published technical standard.'};
